const WORDS = ["SUPERMARKETS", "CATERING", "RESTAURANTS", "IMMIGRATION", "FOODS"];

const CSS = `
.kayal-intro{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(135% 120% at 50% 42%,#14181C 0%,#0A0C0E 55%,#000 100%);overflow:hidden;}
.kayal-intro::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 240px 40px rgba(0,0,0,.55);}
.kayal-intro .ki-bigwords{position:absolute;inset:0;pointer-events:none;}
.kayal-intro .ki-bigword{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:inline-flex;gap:.01em;
  color:#F2E9CC;font:300 clamp(38px,8.5vw,88px)/1 var(--font-montserrat),-apple-system,"Helvetica Neue",Helvetica,Arial,sans-serif;
  letter-spacing:.01em;text-transform:uppercase;white-space:nowrap;}
.kayal-intro .ki-bigword .ki-cmask{display:inline-block;overflow:hidden;}
.kayal-intro .ki-bigword .ki-char{display:inline-block;will-change:transform;}
.kayal-intro .ki-center{display:flex;align-items:center;justify-content:center;width:min(74%,700px);will-change:transform;}
.kayal-intro .ki-logo{width:100%;filter:drop-shadow(0 16px 46px rgba(0,0,0,.5));}
.kayal-intro .ki-logo svg{width:100%;height:auto;display:block;overflow:visible;}
.kayal-intro .ki-words{position:absolute;left:0;right:0;top:50%;margin-top:100px;display:flex;flex-wrap:wrap;
  justify-content:center;align-items:center;gap:12px 30px;padding:0 28px;pointer-events:none;}
.kayal-intro .ki-words .ki-word{display:inline-flex;gap:.14em;color:#E6DABA;
  font:300 clamp(11px,1.45vw,15px)/1.05 var(--font-montserrat),-apple-system,"Helvetica Neue",Helvetica,Arial,sans-serif;
  text-transform:uppercase;white-space:nowrap;}
.kayal-intro .ki-words .ki-cmask{display:inline-block;overflow:hidden;}
.kayal-intro .ki-words .ki-char{display:inline-block;will-change:transform;}
.kayal-intro .ki-bigwords{visibility:hidden;}
.kayal-intro .ki-center{visibility:hidden;}
.kayal-intro .ki-words{visibility:hidden;}
`;

export default function LoadingScreen({ oncePerSession = true }: { oncePerSession?: boolean }) {
  const [hidden, setHidden] = useState(
    () => Boolean(oncePerSession && introPlayed),
  );
  const rootRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (oncePerSession && introPlayed) return;
    const root = rootRef.current;
    if (!root) return;

    document.body.style.overflow = "hidden";
    let safetyTimer: ReturnType<typeof setTimeout>;
    const finish = () => {
      clearTimeout(safetyTimer);
      introPlayed = true;
      document.body.style.overflow = "";
      setHidden(true);
    };
    safetyTimer = setTimeout(finish, 8000);

    const splitWord = (word: Element) => {
      const text = word.textContent || "";
      word.textContent = "";
      const chs: HTMLElement[] = [];
      text.split("").forEach((ch) => {
        const m = document.createElement("span"); m.className = "ki-cmask";
        const c = document.createElement("span"); c.className = "ki-char"; c.textContent = ch;
        m.appendChild(c); word.appendChild(m); chs.push(c);
      });
      return chs;
    };

    const logo = root.querySelector(".ki-logo") as HTMLElement;
    const center = root.querySelector(".ki-center") as HTMLElement;
    const bigWords = Array.from(root.querySelectorAll(".ki-bigword")).map(splitWord);
    const smallChars: HTMLElement[] = [];
    root.querySelectorAll(".ki-words .ki-word").forEach((w) => splitWord(w).forEach((c) => smallChars.push(c)));

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    if (reduce) {
      finish();
      return;
    }

    // getBBox() returns zeros when ancestors are visibility:hidden — unhide for measurement (iOS Safari).
    const bwEl = root.querySelector(".ki-bigwords") as HTMLElement | null;
    const cnEl = root.querySelector(".ki-center") as HTMLElement | null;
    const kwEl = root.querySelector(".ki-words") as HTMLElement | null;
    if (bwEl) bwEl.style.visibility = "visible";
    if (cnEl) cnEl.style.visibility = "visible";
    if (kwEl) kwEl.style.visibility = "visible";

    const pathX = (p: SVGPathElement, index: number) => {
      try {
        return p.getBBox().x;
      } catch {
        return index;
      }
    };

    const groupOrder = ["wordmark", "waves", "palmTrunk", "palmFronds", "lagoon", "tm"];
    const cfg: Record<string, { base: number; stagger: number; draw: number; w: number }> = {
      wordmark: { base: 0.15, stagger: 0.13, draw: 0.85, w: 5 },
      waves: { base: 1.10, stagger: 0.06, draw: 0.70, w: 4 },
      palmTrunk: { base: 1.45, stagger: 0.03, draw: 0.50, w: 3.5 },
      palmFronds: { base: 1.65, stagger: 0.045, draw: 0.50, w: 3.5 },
      lagoon: { base: 2.05, stagger: 0.06, draw: 0.45, w: 3 },
      tm: { base: 2.35, stagger: 0.05, draw: 0.40, w: 3 },
    };
    const DRAW_SCALE = 0.72;

    type Item = { p: SVGPathElement; fill: string; len: number; i: number; c: { base: number; stagger: number; draw: number; w: number } };
    const items: Item[] = [];
    let drawEndRel = 0;
    groupOrder.forEach((g) => {
      const grp = logo.querySelector("#" + g);
      if (!grp) return;
      const paths = Array.from(grp.querySelectorAll("path")) as SVGPathElement[];
      paths.sort((a, b) => pathX(a, 0) - pathX(b, 1));
      paths.forEach((p, i) => {
        const fill = p.getAttribute("fill") || "#fff";
        let len = 0; try { len = p.getTotalLength(); } catch { len = 400; }
        const c = cfg[g];
        const t = (c.base + i * c.stagger) * DRAW_SCALE;
        const endT = t + c.draw * DRAW_SCALE * 0.55 + 0.5 * DRAW_SCALE;
        if (endT > drawEndRel) drawEndRel = endT;
        items.push({ p, fill, len, i, c });
      });
    });

    const BIG_STEP = 0.62, BIG_ENTER = 0.34, BIG_HOLD = 0.12, BIG_EXIT = 0.28, bigStart = 0.15;
    const BIG_END = bigStart + (bigWords.length - 1) * BIG_STEP + BIG_ENTER + BIG_HOLD + BIG_EXIT;

    const ctx = gsap.context(() => {
      // prime
      items.forEach((o) => gsap.set(o.p, {
        fillOpacity: 0, stroke: o.fill, strokeWidth: o.c.w, strokeOpacity: 1,
        strokeDasharray: o.len, strokeDashoffset: o.len, strokeLinecap: "round", strokeLinejoin: "round",
      }));
      gsap.set(center, { y: 0, scale: 1, transformOrigin: "50% 50%" });
      bigWords.forEach((chs) => gsap.set(chs, { yPercent: 120 }));
      gsap.set(smallChars, { yPercent: 120 });

      // Containers are visible for measurement; GSAP has primed everything invisible.
      if (reduce) {
        items.forEach((o) => gsap.set(o.p, { fillOpacity: 1, strokeOpacity: 0, strokeDashoffset: 0 }));
        gsap.set(center, { y: -64, scale: 0.72 });
        bigWords.forEach((chs) => gsap.set(chs, { yPercent: -120 }));
        gsap.set(smallChars, { yPercent: 0 });
        gsap.to(root, { autoAlpha: 0, duration: 0.5, delay: 0.8, onComplete: finish });
        return;
      }

      const tl = gsap.timeline({ onComplete: () => gsap.to(root, { autoAlpha: 0, duration: 0.7, delay: 0.5, onComplete: finish }) });

      // 1) big words, one at a time
      bigWords.forEach((chs, k) => {
        const T = bigStart + k * BIG_STEP;
        tl.to(chs, { yPercent: 0, duration: BIG_ENTER, ease: "power3.out", stagger: 0.025 }, T);
        tl.to(chs, { yPercent: -120, duration: BIG_EXIT, ease: "power2.in", stagger: 0.015 }, T + BIG_ENTER + BIG_HOLD);
      });
      // 2) logo self-draw
      const LOGO_START = BIG_END + 0.15;
      items.forEach((o) => {
        const t = LOGO_START + (o.c.base + o.i * o.c.stagger) * DRAW_SCALE;
        tl.to(o.p, { strokeDashoffset: 0, duration: o.c.draw * DRAW_SCALE, ease: "power1.inOut" }, t);
        tl.to(o.p, { fillOpacity: 1, strokeOpacity: 0, duration: 0.5 * DRAW_SCALE, ease: "power1.out" }, t + o.c.draw * DRAW_SCALE * 0.55);
      });
      // 3) lift + shrink, then spread small words
      const moveT = LOGO_START + drawEndRel + 0.2;
      tl.to(center, { y: -64, scale: 0.72, duration: 0.75, ease: "power3.inOut" }, moveT);
      tl.to(smallChars, { yPercent: 0, duration: 0.55, ease: "power3.out", stagger: 0.02 }, moveT + 0.4);
    }, root);

    return () => { ctx.revert(); document.body.style.overflow = ""; };
  }, [oncePerSession]);

  if (hidden) return null;

  return (
    <div ref={rootRef} className="kayal-intro" aria-hidden="true" role="presentation">
      <style>{CSS}</style>
      <div className="ki-bigwords">
        {WORDS.map((w) => <span className="ki-bigword" key={"big-" + w}>{w}</span>)}
      </div>
      <div className="ki-center">
        <div className="ki-logo" dangerouslySetInnerHTML={{ __html: LOGO_SVG }} />
      </div>
      <div className="ki-words">
        {WORDS.map((w) => <span className="ki-word" key={"sm-" + w}>{w}</span>)}
      </div>
    </div>
  );
}
